<template>
    <el-dialog v-model="dialogVisible" :title="t('remark')" width="35%" :before-close="handleClose"
        :close-on-click-modal="true" :close-on-press-escape="true" class="remark-dialog">
        <div class="remark-border remark-border-spacer"></div>
        <div class="remark-content">
            <el-input 
                ref="remarkInputRef"
                v-model="remarkText" 
                type="textarea" 
                :placeholder="t('enterRemark')" 
                :maxlength="maxLength"
                :rows="6" 
                resize="none" 
                show-word-limit 
                class="remark-input" 
                autofocus
                @input="handleInput" 
            />
        </div>
        <template #footer>
            <div class="dialog-footer">
                <el-button @click="handleCancel" class="cancel-btn">
                    {{ t('cancel') }}
                </el-button>
                <el-button type="primary" @click="handleConfirm" class="confirm-btn" :disabled="!hasChanges">
                    {{ t('confirm') }}
                </el-button>
            </div>
        </template>
    </el-dialog>
</template>

<script setup>
import { ref, watch, computed, nextTick } from 'vue';
import { useI18n } from 'vue-i18n';

const { t } = useI18n();

// Props
const props = defineProps({
    visible: {
        type: Boolean,
        default: false
    },
    session: {
        type: Object,
        default: () => ({})
    },
    maxLength: {
        type: Number,
        default: 120
    }
});

// Emits
const emit = defineEmits(['update:visible', 'save', 'cancel']);

// 响应式数据
const dialogVisible = ref(false);
const remarkText = ref('');
const originalRemark = ref('');
const remarkInputRef = ref(null);

// 计算属性 - 检查内容是否有变化
const hasChanges = computed(() => {
    return remarkText.value.trim() !== originalRemark.value;
});

// 监听visible变化
watch(() => props.visible, (newVal) => {
    dialogVisible.value = newVal;
    if (newVal && props.session) {
        // 当弹窗打开时，初始化备注内容
        const remark = props.session.remark || '';
        remarkText.value = remark;
        originalRemark.value = remark;
    }
});

// 监听dialogVisible变化，同步到父组件
watch(dialogVisible, (newVal) => {
    emit('update:visible', newVal);
    
    // 当弹窗显示时，延迟聚焦输入框
    if (newVal) {
        // 使用多重延迟确保聚焦成功
        nextTick(() => {
            setTimeout(() => {
                focusInput();
            }, 150);
        });
    }
});

// 聚焦输入框的函数
const focusInput = () => {
    if (!remarkInputRef.value) return;
    
    try {
        // Element Plus v2.x 推荐的聚焦方法
        if (typeof remarkInputRef.value.focus === 'function') {
            remarkInputRef.value.focus();
            
            // 设置光标位置到文本末尾
            nextTick(() => {
                if (remarkText.value) {
                    const textareaEl = remarkInputRef.value.textarea;
                    if (textareaEl) {
                        const length = remarkText.value.length;
                        textareaEl.setSelectionRange(length, length);
                    }
                }
            });
        } else {
            // 备用方案：直接操作DOM元素
            const textareaEl = remarkInputRef.value.$el?.querySelector('textarea') || 
                              remarkInputRef.value.textarea;
            
            if (textareaEl) {
                textareaEl.focus();
                if (remarkText.value) {
                    const length = remarkText.value.length;
                    textareaEl.setSelectionRange(length, length);
                }
            }
        }
    } catch (error) {
        console.warn('Failed to focus textarea:', error);
        // 最后的备用方案
        setTimeout(() => {
            const textarea = document.querySelector('.remark-input textarea');
            if (textarea) {
                textarea.focus();
                if (remarkText.value) {
                    textarea.setSelectionRange(remarkText.value.length, remarkText.value.length);
                }
            }
        }, 50);
    }
};

// 处理输入
const handleInput = (value) => {
    remarkText.value = value;
};

// 处理确认
const handleConfirm = () => {
    // 发送保存事件，包含备注内容（允许空备注，用于清除备注）
    emit('save', remarkText.value.trim());
    dialogVisible.value = false;
};

// 处理取消
const handleCancel = () => {
    // 恢复原始备注内容
    remarkText.value = originalRemark.value;
    emit('cancel');
    dialogVisible.value = false;
};

// 处理关闭
const handleClose = (done) => {
    // 恢复原始备注内容
    remarkText.value = originalRemark.value;
    emit('cancel');
    done();
};
</script>


