/**
 * 角色相关API服务
 * 提供角色管理、角色会话等功能
 */
import { ApiClient } from './client-api';
import { ApiResponse } from './definitions';
import {
    API_CHARACTER_LIST,
    API_CHARACTER_CREATE,
    API_CHARACTER_UPDATE,
    API_CHARACTER_DELETE,
    API_CHARACTER_DETAIL,
    API_CHARACTER_CHAT_LIST,
    API_CHARACTER_SESSION_CREATE,
    API_CHARACTER_SESSION_DELETE,
    API_CHARACTER_SESSION_REMARK,
    API_CHARACTER_SEND,
    API_CHARACTER_MESSAGE_LIST
} from './api-url';
import {
    CharacterInfo,
    CharacterListResponseInfo,
    CharacterResponseInfo,
    CharacterChatCreateResponseInfo,
    CharacterChatListResponseInfo,
    DeleteResponseInfo,
    CharacterCreateParams,
    CharacterUpdateParams,
    CharacterMessageSendParams,
    CharacterMessageSendResponseInfo,
    CharacterMessageListResponseInfo,
    CharacterSessionDeleteParams,
    CharacterSessionDeleteResponseInfo,
    CharacterSessionRemarkResponseInfo
} from '../models/character-models';

/**
 * 角色API服务类
 * 集中管理所有角色相关的API调用
 */
export class ApiCharacter {
    /**
     * 获取角色列表
     * @param page_size 每页数量，默认为10，最大50
     * @param cursor 游标ID，用于分页（传入上一页最后一条记录的ID）
     * @param creator_id 创建者ID，用于筛选特定创建者的角色
     * @returns 角色列表响应
     */
    static async getCharacterList(page_size: number = 10, cursor: number | null = null, creator_id: number | null = null): Promise<ApiResponse<CharacterListResponseInfo>> {
        return await ApiClient.post(
            API_CHARACTER_LIST,
            { page_size, cursor, creator_id },
            CharacterListResponseInfo
        );
    }

    /**
     * 获取角色会话列表
     * @param character_id 角色ID
     * @param page_size 每页数量，默认为10，最大50
     * @param cursor 游标ID，用于分页（传入上一页最后一条记录的ID）
     * @param model 使用的AI模型
     * @returns 角色会话列表响应
     */
    static async getCharacterSessionList(character_id: number, page_size: number = 10, cursor: number | null = null, model: string | null = null): Promise<ApiResponse<CharacterChatListResponseInfo>> {
        return await ApiClient.post(
            API_CHARACTER_CHAT_LIST,
            { character_id, page_size, cursor, model },
            CharacterChatListResponseInfo
        );
    }

    /**
     * 创建角色
     * @param params 角色创建参数
     * @returns 创建的角色信息
     */
    static async createCharacter(params: CharacterCreateParams): Promise<ApiResponse<CharacterResponseInfo>> {
        return await ApiClient.post(
            API_CHARACTER_CREATE,
            params,
            CharacterResponseInfo
        );
    }

    /**
     * 创建角色聊天会话
     * @param character_id 角色ID
     * @param model 使用的AI模型（必填）
     * @param title 会话标题（可选）
     * @returns 创建的会话信息
     */
    static async createCharacterChat(character_id: number, model: string, title?: string | null): Promise<ApiResponse<CharacterChatCreateResponseInfo>> {
        const requestData: any = { character_id, model };
        if (title) {
            requestData.title = title;
        }

        return await ApiClient.post(
            API_CHARACTER_SESSION_CREATE,
            requestData,
            CharacterChatCreateResponseInfo
        );
    }

    /**
     * 更新角色信息
     * @param params 角色更新参数
     * @returns 更新结果
     */
    static async updateCharacter(params: CharacterUpdateParams): Promise<ApiResponse<CharacterResponseInfo>> {
        return await ApiClient.post(
            API_CHARACTER_UPDATE,
            params,
            CharacterResponseInfo
        );
    }

    /**
     * 删除角色
     * @param character_id 角色ID
     * @returns 删除结果
     */
    static async deleteCharacter(character_id: number): Promise<ApiResponse<DeleteResponseInfo>> {
        return await ApiClient.post(
            API_CHARACTER_DELETE,
            { character_id },
            DeleteResponseInfo
        );
    }

      /**
     * 获取会话消息列表
     * @param session_id 会话ID
     * @param page_size 每页数量，默认为20，最大50
     * @param cursor 游标ID，用于分页（传入上一页最后一条记录的ID）
     * @returns 消息列表
     */
    static async getCharacterChatMessageList(session_id: number, page_size: number = 20, cursor: number | null = null): Promise<ApiResponse<CharacterMessageListResponseInfo>> {
        return await ApiClient.post(
            API_CHARACTER_MESSAGE_LIST,
            { session_id, page_size, cursor },
            CharacterMessageListResponseInfo
        );
    }

    /**
     * 获取角色详情
     * @param character_id 角色ID
     * @returns 角色详情信息
     */
    static async getCharacterDetail(character_id: number): Promise<ApiResponse<CharacterResponseInfo>> {
        return await ApiClient.post(
            API_CHARACTER_DETAIL,
            { character_id },
            CharacterResponseInfo
        );
    }

    /**
     * 发送角色消息
     * @param character_id 角色ID
     * @param content 消息内容
     * @param model 使用的AI模型
     * @param session_id 会话ID（可选，如果不提供则创建新会话）
     * @returns 发送消息响应
     */
    static async sendCharacterMessage(
        character_id: number,
        content: string,
        model: string | null,
        session_id?: number | null,
        enable_search?: boolean | null,
    ): Promise<ApiResponse<CharacterMessageSendResponseInfo>> {
        return await ApiClient.post(
            API_CHARACTER_SEND,
            {
                character_id,
                content,
                model,
                session_id,
                enable_search,
            },
            CharacterMessageSendResponseInfo
        );
    }

    /**
     * 删除角色会话
     * @param session_id 会话ID
     * @returns 删除结果
     */
    static async deleteCharacterSession(session_id: number): Promise<ApiResponse<CharacterSessionDeleteResponseInfo>> {
        return await ApiClient.post(
            API_CHARACTER_SESSION_DELETE,
            { id: session_id },
            CharacterSessionDeleteResponseInfo
        );
    }

    /**
     * 更新角色会话备注
     * @param params 备注更新参数
     * @returns 更新结果
     */
    static async updateCharacterSessionRemark(id: string, remark: string): Promise<ApiResponse<CharacterSessionRemarkResponseInfo>> {
        return await ApiClient.post(
            API_CHARACTER_SESSION_REMARK,
            { id, remark },
            CharacterSessionRemarkResponseInfo
        );
    }
}