/**
 * AI模型验证工具类
 * 提供AI工具会话中模型验证和设置的相关方法
 */

import { useChatModelStore } from '@/store/modules/chat-model';

// 内部使用的store实例
let chatModelStore = null;

/**
 * 获取chatModel store实例
 * 支持懒加载，确保在Vue应用上下文中正确初始化
 */
const getChatModelStore = () => {
    if (!chatModelStore) {
        chatModelStore = useChatModelStore();
    }
    return chatModelStore;
};

/**
 * AI工具模型验证与设置公共方法
 * 验证会话中的模型是否在当前可用模型列表中，如果不可用则不设置模型（保持输入框不显示状态）
 * 
 * @param {Object} params - 参数对象
 * @param {string} params.sessionModel - 会话中存储的模型名称
 * @param {string} params.modelType - 模型类型：'text' | 'image_analysis' | 'reasoning' | 'vision' | 'image_gen' | 'video_gen' | 'deep_search'
 * @param {Object} params.currentModelRef - 当前模型的ref对象
 * @returns {Promise<string|null>} - 验证后的模型名称，null表示模型不可用
 */
export async function validateAndSetAIModel({
    sessionModel,
    modelType,
    currentModelRef
}) {
    const store = getChatModelStore();

    // 如果会话没有模型，清空当前模型（不显示输入框）
    if (!sessionModel) {
        currentModelRef.value = '';
        console.info('No session model, clearing current model');
        return null;
    }

    try {
        // 获取当前可用的模型列表
        const availableModels = await getModelsByType(store, modelType);
        const isModelAvailable = availableModels.some(model => model.name === sessionModel);
        
        if (isModelAvailable) {
            // 模型可用，直接设置
            currentModelRef.value = sessionModel;
            console.info(`Model "${sessionModel}" is available and set`);
            return sessionModel;
        } else {
            // 模型不可用（旧模型），清空当前模型，不显示输入框
            currentModelRef.value = '';
            console.warn(`Model "${sessionModel}" is not available (outdated), clearing current model to hide input`);
            return null;
        }
    } catch (error) {
        console.error('Failed to validate model:', error);
        // 发生错误时也清空模型，避免显示无效的输入框
        currentModelRef.value = '';
        console.warn('Error occurred, clearing current model to hide input');
        return null;
    }
}

/**
 * 根据模型类型获取对应的模型列表
 * 
 * @param {Object} store - 聊天模型状态管理器
 * @param {string} modelType - 模型类型
 * @returns {Promise<Array>} - 模型列表
 */
async function getModelsByType(store, modelType) {
    switch (modelType) {
        case 'text':
            return await store.getTextModels();
        case 'reasoning':
            return await store.getReasoningModels();
        case 'image_analysis':
            return await store.getImageAnalysisModels();
        case 'vision':
            return await store.getVisionModels();
        case 'image_gen':
            return await store.getImageGenModels();
        case 'video_gen':
            return await store.getVideoGenModels();
        case 'deep_search':
            return await store.getDeepSearchModels();
        default:
            console.warn(`Unsupported model type: ${modelType}`);
            return [];
    }
}

/**
 * 批量验证多个会话的模型
 * 用于处理会话列表加载后的批量验证场景
 * 
 * @param {Array} sessions - 会话列表
 * @param {string} modelType - 模型类型
 * @returns {Promise<Array>} - 验证结果数组，包含每个会话的验证状态
 */
export async function batchValidateSessionModels(sessions, modelType) {
    if (!sessions || !Array.isArray(sessions)) {
        console.warn('batchValidateSessionModels: Invalid sessions array');
        return [];
    }

    const store = getChatModelStore();

    try {
        const availableModels = await getModelsByType(store, modelType);
        const availableModelNames = availableModels.map(model => model.name);
        
        return sessions.map(session => ({
            sessionId: session.id,
            originalModel: session.ai_model,
            isValid: session.ai_model && availableModelNames.includes(session.ai_model),
            recommendedModel: availableModels.length > 0 ? availableModels[0].name : null
        }));
    } catch (error) {
        console.error('Failed to batch validate session models:', error);
        return sessions.map(session => ({
            sessionId: session.id,
            originalModel: session.ai_model,
            isValid: false,
            recommendedModel: null,
            error: error.message
        }));
    }
}

/**
 * 检查模型是否在指定类型的可用模型列表中
 * 
 * @param {string} modelName - 要检查的模型名称
 * @param {string} modelType - 模型类型
 * @returns {Promise<boolean>} - 模型是否可用
 */
export async function isModelAvailable(modelName, modelType) {
    if (!modelName || !modelType) {
        return false;
    }

    const store = getChatModelStore();

    try {
        const availableModels = await getModelsByType(store, modelType);
        return availableModels.some(model => model.name === modelName);
    } catch (error) {
        console.error('Failed to check model availability:', error);
        return false;
    }
}

/**
 * 获取指定模型类型的默认模型
 * 
 * @param {string} modelType - 模型类型
 * @returns {Promise<string|null>} - 默认模型名称
 */
export async function getDefaultModel(modelType) {
    if (!modelType) {
        return null;
    }

    const store = getChatModelStore();

    try {
        const availableModels = await getModelsByType(store, modelType);
        return availableModels.length > 0 ? availableModels[0].name : null;
    } catch (error) {
        console.error('Failed to get default model:', error);
        return null;
    }
}

/**
 * 获取指定模型类型的所有可用模型
 * 
 * @param {string} modelType - 模型类型
 * @returns {Promise<Array>} - 可用模型列表
 */
export async function getAvailableModels(modelType) {
    if (!modelType) {
        return [];
    }

    const store = getChatModelStore();

    try {
        return await getModelsByType(store, modelType);
    } catch (error) {
        console.error('Failed to get available models:', error);
        return [];
    }
}

/**
 * 模型类型常量定义
 */
