    REASONING: 'reasoning',
    IMAGE_ANALYSIS: 'image_analysis',
    VISION: 'vision',
    IMAGE_GEN: 'image_gen',
    VIDEO_GEN: 'video_gen',
    DEEP_SEARCH: 'deep_search'
