<template>
    <div class="chat-sidebar">
        <!-- 筛选头部 -->
        <div class="chat-header" v-if="selectedCharacter">
            <div class="header-title">{{ t('chatList') }}</div>
            <div class="filter-container">
                <el-select v-model="chatFilter" :placeholder="t('filterChats')" class="filter-select" size="small"
                    @change="onFilterChange" :loading="isLoadingModels">
                    <el-option v-for="item in filterItems" :key="item.key" :label="item.title" :value="item.key" />
                </el-select>
            </div>
        </div>

        <div v-if="showEmptyState" class="empty-state">
            <p class="empty-text">{{ t('noChatRecords') }}</p>
        </div>
        <div v-else-if="!selectedCharacter" class="empty-state">
            <p class="empty-text">{{ t('selectCharacterToViewChats') }}</p>
        </div>
        <div v-else class="chat-container">
            <ListMore :loading="pagination.loading"
                :finished="!pagination.hasMore && !pagination.loading && chatSessions.length > 0" :distance="50"
                :delay="200" container-class="chat-sessions-list" @load-more="handleLoadMore">
                <div v-for="session in filteredChatSessions" :key="session.id" class="chat-session-item"
                    :class="{ 'active': selectedSession?.id === session.id }" @click.stop="selectSession(session)">
                    <div class="session-content">
                        <div class="session-wrapper">
                            <div class="session-title">{{ session.user_name }}</div>
                            <div v-if="session.last_message_time" class="session-meta">{{
                                convertUtcToLocal(session.last_message_time) }}</div>
                            <div v-if="!session.isNew" class="session-action-buttons">
                                <div class="session-action-btn" @click.stop="editRemark(session)" :title="t('edit')">
                                    <l-img src="/static/images/conversation/edit_icon.png" w="12px" h="12px" />
                                </div>
                                <div class="session-action-btn" @click.stop="shareSession(session)" :title="t('share')">
                                    <l-img src="/static/images/conversation/share_icon.png" w="12px" h="12px" />
                                </div>
                                <div class="session-action-btn" @click.stop="deleteSession(session)"
                                    :title="t('delete')">
                                    <l-img src="/static/images/conversation/delete_icon.png" w="12px" h="12px" />
                                </div>
                            </div>
                        </div>
                        <div class="session-preview">
                            {{ session.last_message_content ?? ' ' }}
                        </div>
                        <div class="session-preview-count">
                            <div class="preview-item">
                                <l-img src="/static/images/conversation/session_message_count.png" w="12px" h="12px" />
                                {{ session.message_count || 0 }}
                            </div>
                            <div v-if="session.ai_model" class="preview-item model-info">
                                <l-img src="/static/images/conversation/model_icon.png" w="16px" h="16px" />
                                <span>{{ session.ai_model }}</span>
                            </div>
                        </div>
                        <div class="session-list-remark" v-if="session.remark">
                            {{`${t('remark')}: ${session.remark}`}}
                        </div>
                    </div>
                </div>
            </ListMore>
        </div>
        <div class="sidebar-footer" v-if="selectedCharacter">
            <button class="new-chat-btn" @click="createNewChat">
              <l-img src="/static/images/chat-sidebar-add-icon.png" w="20px" h="20px" />
                <span>{{ t('newChat') }}</span>
            </button>
        </div>
    </div>
</template>

<script setup>
import { ref, computed, watch } from 'vue';
import { ElSelect, ElOption, ElMessage } from 'element-plus';
 import LImg from '@/components/l-img.vue';
import ListMore from '@/components/list-more.vue';
import { useCharacterList } from '@/composables/useCharacterList';
import { useChatModelStore } from '@/store/modules/chat-model';
import { MODEL_CAPABILITIES } from '@/models/chat-model-models';
import { convertUtcToLocal } from '@/utils/util';
import { t } from '@/language';
const chatModelStore = useChatModelStore();

// Props
const props = defineProps({
    selectedCharacter: {
        type: Object,
        default: null
    },
    selectedSession: {
        type: Object,
        default: null
    },
    chatSessions: {
        type: Array,
        default: () => []
    },
    pagination: {
        type: Object,
        default: () => ({
            loading: true,
            hasMore: true
        })
    },
    modelType: {
        type: String,
        default: ''
    }
});

// Emits
const emit = defineEmits([
    'selectSession', 
    'createNewChat', 
    'editRemark', 
    'shareSession', 
    'deleteSession',
    'scroll',
    'filterChange'
]);

// 响应式数据
const chatFilter = ref(0);
const filterItems = ref([]);
const isLoadingModels = ref(false);


// 根据modelType获取模型数据
const fetchModelsByType = async () => {
    if (!props.modelType) {
        // 如果没有指定modelType，使用默认的筛选项
        filterItems.value = [
            { key: 0, title: t('all'), is_selected: 1 }
        ];
        return;
    }

    try {
        isLoadingModels.value = true;
        let modelList = [];

        switch (props.modelType) {
            case MODEL_CAPABILITIES.TEXT:
                modelList = await chatModelStore.getTextModels();
                break;
            case MODEL_CAPABILITIES.REASONING:
                modelList = await chatModelStore.getReasoningModels();
                break;
            case MODEL_CAPABILITIES.IMAGE_ANALYSIS:
                modelList = await chatModelStore.getImageAnalysisModels();
                break;
            case MODEL_CAPABILITIES.VISION:
                modelList = await chatModelStore.getVisionModels();
                break;
            case MODEL_CAPABILITIES.IMAGE_GEN:
                modelList = await chatModelStore.getImageGenModels();
                break;
            default:
                console.warn(`Unsupported modelType: ${props.modelType}`);
                modelList = [];
        }

        // 构建筛选项：全部 + 各个模型
        const items = [
            { key: 0, title: t('all'), is_selected: 1 }
        ];

        if (modelList && modelList.length > 0) {
            modelList.forEach((model, index) => {
                items.push({
                    key: index + 1,
                    title: model.name || model.title,
                    name: model.name,
                    is_selected: 0,
                    ...model
                });
            });
        }

        filterItems.value = items;
    } catch (error) {
        console.error(`Failed to fetch models for type ${props.modelType}:`, error);
        // 出错时使用默认筛选项
        filterItems.value = [
            { key: 0, title: t('all'), is_selected: 1 }
        ];
    } finally {
        isLoadingModels.value = false;
    }
};

// 监听modelType变化，自动获取对应的模型数据
watch(() => props.modelType, () => {
    fetchModelsByType();
}, { immediate: true });

// 筛选变化处理方法
const onFilterChange = (value) => {
    console.log('Filter changed to:', value);
    
    // 获取选中的筛选项
    const selectedFilter = filterItems.value.find(item => item.key === value);
    
    // 构建筛选参数
    const filterParams = {
        filterType: value === 0 ? 'all' : 'model',
        modelName: selectedFilter?.name || null,
        modelInfo: selectedFilter || null
    };
    
    // 向父组件发送筛选变化事件
    emit('filterChange', filterParams);
};

// 处理加载更多事件
const handleLoadMore = () => {
    if (!props.pagination.hasMore) {
        return;
    }
    
    emit('scroll', { target: { scrollTop: 999999, scrollHeight: 999999, clientHeight: 0 } });
};

const filteredChatSessions = computed(() => {
    if (!props.chatSessions.length) return [];
    
    // 如果选择的是"全部"（key为0），返回所有会话
    if (chatFilter.value === 0) {
        return props.chatSessions;
    }
    
    // 根据选择的模型筛选会话
    const selectedFilter = filterItems.value.find(item => item.key === chatFilter.value);
    if (selectedFilter && selectedFilter.name) {
        return props.chatSessions.filter(session => 
            session.ai_model === selectedFilter.name
        );
    }
    
    return props.chatSessions;
});

const showEmptyState = computed(() => {
    return props.chatSessions.length === 0 && !props.pagination.loading;
});

// 方法
const selectSession = (session) => {
    emit('selectSession', session);
};

const createNewChat = () => {
    let hasNewSession = props.chatSessions.find(session => session.isNew);
    if (hasNewSession) {
        ElMessage.warning(t('hasNewSession'));
        return;
    }

    let modelName = filterItems.value[1].name || '';
    emit('createNewChat', modelName);
};

const editRemark = (session) => {
    emit('editRemark', session);
};

const shareSession = (session) => {
    emit('shareSession', session);
};

const deleteSession = (session) => {
    emit('deleteSession', session);
};
</script>

