import { useI18n } from 'vue-i18n';

/**
 * 角色列表相关工具函数
 * @returns {Object} 角色列表相关的工具方法
 */
export function useCharacterList() {
    const { t } = useI18n();

    /**
     * 根据创建者ID获取创建者名称
     * @param {number} creatorId - 创建者ID
     * @returns {string} 创建者名称
     */
    const getCreatorName = (creatorId) => {
        const creatorMap = {
            1: 'KAKA',
            2: 'Admin',
            3: 'System'
        };
        return creatorMap[creatorId] || 'Unknown';
    };

    /**
     * 格式化日期
     * @param {string} dateString - 日期字符串
     * @returns {string} 格式化后的日期
     */
    const formatDate = (dateString) => {
        if (!dateString) return '';
        
        const date = new Date(dateString);
        if (isNaN(date.getTime())) return '';
        
        return date.toLocaleDateString('en-US', {
            month: '2-digit',
            day: '2-digit',
            year: 'numeric',
            hour: '2-digit',
            minute: '2-digit'
        }).replace('AM', '').replace('PM', '');
    };

    /**
     * 格式化日期为 mm/dd, yyyy 格式
     * @param {string} dateString - 日期字符串
     * @param {boolean} hasTime - 是否包含时间
     * @returns {string} 格式化后的日期
     */
    const formatDateOnly = (dateString, hasTime = false) => {
        if (!dateString) return '';
        
        const date = new Date(dateString);
        if (isNaN(date.getTime())) return '';
        
        const month = String(date.getMonth() + 1).padStart(2, '0');
        const day = String(date.getDate()).padStart(2, '0');
        const year = date.getFullYear();
        
        if (hasTime) {
            const hour = String(date.getHours()).padStart(2, '0');
            const minute = String(date.getMinutes()).padStart(2, '0');
            return `${month}/${day}, ${year} ${hour}:${minute}`;
        }
        
        return `${month}/${day}, ${year}`;
    };

    /**
     * 格式化数字（大于1000时显示为k）
     * @param {number} num - 数字
     * @returns {string} 格式化后的数字
     */
    const formatNumber = (num) => {
        if (num >= 1000) {
            return (num / 1000).toFixed(1) + 'k';
        }
        return num?.toString();
    };

    /**
     * 构造角色详情数据
     * @param {Object} character - 角色数据
     * @returns {Object} 格式化的角色详情数据
     */
    const formatCharacterDetails = (character) => {
        return {
            title: character.name,
            content: character.preview,
            category: character.name,
            description: character.description,
            characterDetails: {
                name: character.name,
                description: character.description,
                gender: character.gender || 'Unknown',
                age: character.age || 'Unknown'
            },
            creator_name: character.creator_name,
            createdAt: character.created_at,
            chats: character.chat_count || 0
        };
    };

    return {
        getCreatorName,
        formatDate,
        formatDateOnly,
        formatNumber,
        formatCharacterDetails
    };
} 