import { ref, computed, onMounted, onUnmounted, type Ref, type ComputedRef } from 'vue';

// 类型定义
interface PanelConfig {
    defaultPercent: number;
    defaultPixels?: number;  // 新增：默认像素宽度
    minPercent: number;
    maxPercent: number;
    minPixels: number;
    maxPixels: number;
}

interface ResizeEvent {
    leftWidth: number;
    rightWidth: number;
    deltaX?: number;
}

interface ThrottledFunction<T extends (...args: any[]) => any> {
    (...args: Parameters<T>): void;
}

interface UseResizablePanelsOptions {
    leftPanel?: Partial<PanelConfig>;
    rightPanel?: Partial<PanelConfig>;
    storageKey?: string;
    throttleDelay?: number;
}

interface UseResizablePanelsReturn {
    leftPanelWidth: ComputedRef<number>;
    rightPanelWidth: ComputedRef<number>;
    leftPanelWidthPercent: Ref<number>;
    rightPanelWidthPercent: Ref<number>;
    containerWidth: Ref<number>;
    pageStyle: ComputedRef<Record<string, string>>;
    handleFirstDividerResize: (event: ResizeEvent) => void;
    handleSecondDividerResize: (event: ResizeEvent) => void;
    resetToDefaults: () => void;
}

/**
 * 可拖拽面板功能的 Composable
 * @param options 配置选项
 * @returns 拖拽功能相关的响应式数据和方法
 */
export function useResizablePanels(options: UseResizablePanelsOptions = {}): UseResizablePanelsReturn {
    // 默认配置
    const defaultConfig: PanelConfig = {
        defaultPercent: 20,
        defaultPixels: 300, // 默认300px
        minPercent: 10,
        maxPercent: 50,
        minPixels: 200,
        maxPixels: 600
    };

    // 合并配置
    const leftConfig: PanelConfig = { ...defaultConfig, ...options.leftPanel };
    const rightConfig: PanelConfig = { ...defaultConfig, ...options.rightPanel };
    const storageKey = options.storageKey || 'resizable-panels';
    const throttleDelay = options.throttleDelay || 100;

    // 响应式数据 - 如果有defaultPixels，则根据像素计算初始百分比
    const getInitialPercent = (config: PanelConfig): number => {
        if (config.defaultPixels) {
            return (config.defaultPixels / window.innerWidth) * 100;
        }
        return config.defaultPercent;
    };
    
    const leftPanelWidthPercent = ref(getInitialPercent(leftConfig));
    const rightPanelWidthPercent = ref(getInitialPercent(rightConfig));
    const containerWidth = ref(window.innerWidth);

    // 计算实际像素宽度
    const leftPanelWidth = computed(() => {
        const width = (containerWidth.value * leftPanelWidthPercent.value) / 100;
        return Math.max(leftConfig.minPixels, Math.min(leftConfig.maxPixels, width));
    });

    const rightPanelWidth = computed(() => {
        const width = (containerWidth.value * rightPanelWidthPercent.value) / 100;
        return Math.max(rightConfig.minPixels, Math.min(rightConfig.maxPixels, width));
    });

    // 页面CSS变量样式
    const pageStyle = computed(() => ({
        '--left-panel-width': `${leftPanelWidth.value}px`,
        '--right-panel-width': `${rightPanelWidth.value}px`
    }));

    // 智能计算百分比边界 - 以像素限制为主
    const getPercentBounds = (config: PanelConfig): { minPercent: number; maxPercent: number } => {
        // 将像素限制转换为百分比
        const minPercentFromPixels = (config.minPixels / containerWidth.value) * 100;
        const maxPercentFromPixels = (config.maxPixels / containerWidth.value) * 100;
        
        // 像素限制优先，但不能超出合理的百分比范围 (5%-80%)
        const minPercent = Math.max(5, minPercentFromPixels);  // 最少5%，但优先保证像素最小值
        const maxPercent = Math.min(80, maxPercentFromPixels); // 最多80%，但优先保证像素最大值
        
        return { minPercent, maxPercent };
    };

    // 验证并约束百分比
    const constrainPercent = (percent: number, config: PanelConfig): number => {
        const { minPercent, maxPercent } = getPercentBounds(config);
        return Math.max(minPercent, Math.min(maxPercent, percent));
    };

    // 保存设置到 localStorage
    const saveSettings = (): void => {
        try {
            localStorage.setItem(`${storageKey}-left`, leftPanelWidthPercent.value.toString());
            localStorage.setItem(`${storageKey}-right`, rightPanelWidthPercent.value.toString());
        } catch (error) {
            console.warn('Failed to save panel settings to localStorage:', error);
        }
    };

    // 从 localStorage 恢复设置
    const restoreSettings = (): void => {
        try {
            const savedLeft = localStorage.getItem(`${storageKey}-left`);
            const savedRight = localStorage.getItem(`${storageKey}-right`);

            if (savedLeft) {
                const percent = parseFloat(savedLeft);
                if (!isNaN(percent)) {
                    leftPanelWidthPercent.value = constrainPercent(percent, leftConfig);
                }
            }

            if (savedRight) {
                const percent = parseFloat(savedRight);
                if (!isNaN(percent)) {
                    rightPanelWidthPercent.value = constrainPercent(percent, rightConfig);
                }
            }
        } catch (error) {
            console.warn('Failed to restore panel settings from localStorage:', error);
        }
    };

    // 重置到默认值
    const resetToDefaults = (): void => {
        leftPanelWidthPercent.value = getInitialPercent(leftConfig);
        rightPanelWidthPercent.value = getInitialPercent(rightConfig);
        saveSettings();
    };

    // 处理第一个分割线拖拽（左面板和右面板之间）
    const handleFirstDividerResize = ({ leftWidth, rightWidth }: ResizeEvent) => {
        console.log('First divider resize received:', { 
            leftWidth, 
            rightWidth, 
            leftMin: leftConfig.minPixels, 
            leftMax: leftConfig.maxPixels, 
            rightMin: rightConfig.minPixels, 
            rightMax: rightConfig.maxPixels 
        });

        // 应用约束逻辑：允许在一个面板达到极限时，另一个面板继续调整
        let finalLeftWidth = leftWidth;
        let finalRightWidth = rightWidth;

        // 检查左面板是否在有效范围内
        const leftInBounds = finalLeftWidth >= leftConfig.minPixels && finalLeftWidth <= leftConfig.maxPixels;
        // 检查右面板是否在有效范围内
        const rightInBounds = finalRightWidth >= rightConfig.minPixels && finalRightWidth <= rightConfig.maxPixels;

        // 如果两个面板都超出边界，阻止拖拽
        if (!leftInBounds && !rightInBounds) {
            console.log('Both panels out of bounds, resize blocked:', {
                leftWidth,
                rightWidth,
                leftBounds: [leftConfig.minPixels, leftConfig.maxPixels],
                rightBounds: [rightConfig.minPixels, rightConfig.maxPixels]
            });
            return;
        }

        // 如果左面板超出边界，将其约束到边界值
        if (!leftInBounds) {
            if (finalLeftWidth < leftConfig.minPixels) {
                finalLeftWidth = leftConfig.minPixels;
            } else if (finalLeftWidth > leftConfig.maxPixels) {
                finalLeftWidth = leftConfig.maxPixels;
            }
        }

        // 如果右面板超出边界，将其约束到边界值
        if (!rightInBounds) {
            if (finalRightWidth < rightConfig.minPixels) {
                finalRightWidth = rightConfig.minPixels;
            } else if (finalRightWidth > rightConfig.maxPixels) {
                finalRightWidth = rightConfig.maxPixels;
            }
        }

        console.log('Resize constraints applied:', {
            originalLeft: leftWidth,
            originalRight: rightWidth,
            finalLeft: finalLeftWidth,
            finalRight: finalRightWidth,
            leftInBounds,
            rightInBounds
        });

        // 将像素宽度转换为百分比
        const leftPercent = (finalLeftWidth / containerWidth.value) * 100;
        const rightPercent = (finalRightWidth / containerWidth.value) * 100;

        // 应用边界限制
        const validLeftPercent = constrainPercent(leftPercent, leftConfig);
        const validRightPercent = constrainPercent(rightPercent, rightConfig);
        leftPanelWidthPercent.value = validLeftPercent;
        rightPanelWidthPercent.value = validRightPercent;

        saveSettings();
    };

    // 处理第二个分割线拖拽（右面板和其他区域之间）
    const handleSecondDividerResize = ({ leftWidth }: ResizeEvent) => {
        // 先检查像素边界
        if (leftWidth < rightConfig.minPixels || leftWidth > rightConfig.maxPixels) {
            return; // 超出像素限制，不执行调整
        }

        // 将像素宽度转换为百分比
        const leftPercent = (leftWidth / containerWidth.value) * 100;

        // 应用边界限制
        const validLeftPercent = constrainPercent(leftPercent, rightConfig);

        rightPanelWidthPercent.value = validLeftPercent;

        saveSettings();
    };

    // 窗口尺寸变化处理
    const handleWindowResize = (): void => {
        containerWidth.value = window.innerWidth;

        // 重新验证和调整百分比设置
        const currentLeftPercent = leftPanelWidthPercent.value;
        const currentRightPercent = rightPanelWidthPercent.value;

        leftPanelWidthPercent.value = constrainPercent(currentLeftPercent, leftConfig);
        rightPanelWidthPercent.value = constrainPercent(currentRightPercent, rightConfig);
    };

    // 节流函数
    const createThrottledFunction = <T extends (...args: any[]) => any>(
        fn: T, 
        delay: number
    ): ThrottledFunction<T> => {
        let timeoutId: number | null = null;
        return (...args: Parameters<T>) => {
            if (timeoutId) clearTimeout(timeoutId);
            timeoutId = window.setTimeout(() => fn(...args), delay);
        };
    };

    const throttledHandleWindowResize = createThrottledFunction(handleWindowResize, throttleDelay);

    // 生命周期管理
    onMounted(() => {
        restoreSettings();
        window.addEventListener('resize', throttledHandleWindowResize);
    });

    onUnmounted(() => {
        window.removeEventListener('resize', throttledHandleWindowResize);
    });

    return {
        // 响应式数据
        leftPanelWidth,
        rightPanelWidth,
        leftPanelWidthPercent,
        rightPanelWidthPercent,
        containerWidth,
        pageStyle,
        // 方法
        handleFirstDividerResize,
        handleSecondDividerResize,
        resetToDefaults
    };
} 