<template>
    <div class="character-sidebar">
        <div class="sidebar-header">
            <h2 class="sidebar-title">{{ title || t('characterList') }}</h2>
        </div>

        <ListMore
            :loading="pagination.loading"
            :finished="!pagination.hasMore"
            :distance="50"
            :delay="200"
            container-class="character-container"
            @load-more="handleLoadMore"
        >
            <div v-for="item in formattedItems" :key="item.id" class="character-card"
                :class="{ 'active': selectedItemComputed?.id === item.id }" @click.stop="selectItem(item)">
                <div class="character-header">
                    <div class="character-name">
                        <span>{{ item.title+' - '+item.description }}</span>
                        <div @click.stop="showDetails(item)">
                            <l-img src="/static/images/conversation/chat_prompt_icon.png" w="12px" h="12px" />
                        </div>
                    </div>
                </div>

                <!-- <p class="character-description">{{ item.description }}</p> -->

                <div class="character-prompt">
                    <p class="prompt-text" :title="`${t('prompt')}: ${item.preview}`">{{ t('prompt') }}: {{ item.preview }}</p>
                </div>

                <div class="character-footer">
                    <span class="character-author">{{ item.author }}</span>
                    <div class="character-stats">
                        <l-img :src="statsIcon || '/static/images/conversation/chat_count_icon.png'" w="12px"
                            h="12px" />
                        <span>{{ item.stats }}</span>
                    </div>
                </div>
            </div>
        </ListMore>

        <div class="sidebar-footer">
            <button class="create-character-btn" @click="createItem">
                <l-img src="/static/images/chat-sidebar-add-icon.png" w="20px" h="20px" />
                <span>{{ createButtonText || t('createCharacter') }}</span>
            </button>
        </div>
    </div>
</template>

<script setup>
import { ref, computed } from 'vue';
import { useI18n } from 'vue-i18n';
import { ElMessage } from 'element-plus';
import LImg from '@/components/l-img.vue';
import ListMore from '@/components/list-more.vue';
import { useCharacterList } from '@/composables/useCharacterList';
import { ApiCharacter } from '@/api/api-character';
import { convertUtcToLocal } from '@/utils/util';

const { t } = useI18n();

// Props
const props = defineProps({
    // 基础配置
    title: { type: String, default: '' },
    selectedItem: { type: Object, default: null },
    // API 函数配置
    loadItemsApi: { type: Function, default: null },
    createItemApi: { type: Function, default: null },
    deleteItemApi: { type: Function, default: null },
    createButtonText: { type: String, default: '' },
    emptyText: { type: String, default: '' },
    detailIcon: { type: String, default: '' },
    statsIcon: { type: String, default: '' },
    mockData: { type: Array, default: () => [] }
});

// Emits
const emit = defineEmits(['select', 'create', 'showDetails']);

// 兼容性处理
const selectedItemComputed = computed(() => props.selectedItem);

// 响应式数据
const characters = ref([]);
const loading = ref(false);
const pagination = ref({
    cursor: null,
    hasMore: true,
    pageSize: 20,
    loading: false
});

// 默认模拟数据
const defaultMockCharacters = [];

const {
    formatDate,
    formatNumber
} = useCharacterList();

// 加载角色列表
const loadCharacters = async (isLoadMore = false) => {
    try {
        // 设置loading状态
        if (isLoadMore) {
            pagination.value.loading = true;
        } else {
            loading.value = true;
            // 重置分页状态
            pagination.value.cursor = null;
            pagination.value.hasMore = true;
        }
        // 使用自定义API函数或默认的ApiCharacter方法
        const apiFunction = props.loadItemsApi || ApiCharacter.getCharacterList;
        const response = await apiFunction(
            pagination.value.pageSize,
            pagination.value.cursor
        );

        if (response && response.code === 200 && response.data) {
            const newItems = response.data.items || [];

            if (isLoadMore) {
                // 加载更多时追加数据
                characters.value.push(...newItems);
            } else {
                // 首次加载时替换数据
                characters.value = newItems;
            }

            // 更新分页状态
            pagination.value.hasMore = response.data.has_more || false;

            // 更新cursor为最后一条数据的id
            if (newItems.length > 0) {
                pagination.value.cursor = newItems[newItems.length - 1].id;
            }
        } else {
            throw new Error('API response error');
        }
    } catch (error) {
        console.error('Failed to load characters:', error);

        if(error.status === 401){
            pagination.value.hasMore = false;
        }
        if (!isLoadMore) {
            // 只在首次加载失败时使用模拟数据作为后备
            const mockDataToUse = props.mockData.length > 0 ? props.mockData : defaultMockCharacters;
            characters.value = mockDataToUse;
            pagination.value.hasMore = false;
        }

        ElMessage.warning(t('loadError') || 'Failed to load characters');
    } finally {
        if (isLoadMore) {
            pagination.value.loading = false;
        } else {
            loading.value = false;
        }
    }
};

// 处理加载更多事件
const handleLoadMore = () => {
    if (pagination.value.hasMore && !pagination.value.loading) {
        loadCharacters(true);
    }
};

// 添加新角色到列表顶部
const addCharacter = (newCharacter) => {
    characters.value.unshift(newCharacter);
};

// 从列表中移除角色
const removeCharacter = (characterId) => {
    const index = characters.value.findIndex(character => character.id === characterId);
    if (index > -1) {
        characters.value.splice(index, 1);
    }
};

// 更新列表中的角色
const updateCharacter = (characterId, updates) => {
    const index = characters.value.findIndex(character => character.id === characterId);
    if (index > -1) {
        characters.value[index] = { ...characters.value[index], ...updates };
    }
};

// 重置分页状态
const resetPagination = () => {
    characters.value = [];
    pagination.value.cursor = null;
    pagination.value.hasMore = true;
    pagination.value.loading = false;
    loading.value = false;
};

// 默认格式化函数
const defaultFormatItem = (character) => ({
    id: character.id,
    title: character.name || character.title || '',
    description: character.description,
    preview: character.prompt_preview || character.prompt,
    author: `${character.creator_name} ${t('at')} ${convertUtcToLocal(character.created_at)}`,
    stats: formatNumber(character.usage_count ?? character.chat_count ?? 0),
    creator: character.creator_name,
    createdAt: character.created_at,
});

// 格式化数据
const formattedItems = computed(() => {
    const formatFn = defaultFormatItem;
    return characters.value.map(formatFn);
});

// 方法
const selectItem = (item) => {
    emit('select', item);
};

const createItem = () => {
    emit('create');
};

const showDetails = (item) => {
    emit('showDetails', item);
};

// 暴露方法给父组件
defineExpose({
    // 原有的方法名（向后兼容）
    addCharacter,
    removeCharacter,
    updateCharacter,
    loadCharacters,
    // 新增别名方法
    addItem: addCharacter,
    removeItem: removeCharacter,
    updateItem: updateCharacter,
    loadItems: loadCharacters,
    // 暴露数据属性（向后兼容）
    characters: characters,
    formattedItems: formattedItems,
    pagination: pagination,
    loading: loading,
    // 新增重置方法
    reset: resetPagination
});
</script>

