<template>
    <div
        class="resizable-divider"
        @mousedown="handleMouseDown"
        :class="{ 'dragging': isDragging }"
        :title="t('dragToResize')"
    >
        <div class="divider-line"></div>
    </div>
</template>

<script setup>
import { ref, onUnmounted } from 'vue';
import { useI18n } from 'vue-i18n';

const { t } = useI18n();

// Props
const props = defineProps({
    // 左侧组件的最小宽度
    leftMinWidth: {
        type: Number,
        default: 200
    },
    // 左侧组件的最大宽度
    leftMaxWidth: {
        type: Number,
        default: 600
    },
    // 右侧组件的最小宽度
    rightMinWidth: {
        type: Number,
        default: 200
    },
    // 右侧组件的最大宽度
    rightMaxWidth: {
        type: Number,
        default: 600
    },
    // 分割线类型：'first' 或 'second'
    dividerType: {
        type: String,
        default: 'first',
        validator: (value) => ['first', 'second'].includes(value)
    }
});

// Emits
const emit = defineEmits(['resize']);

// 响应式数据
const isDragging = ref(false);
const startX = ref(0);
const startLeftWidth = ref(0);
const startRightWidth = ref(0);
let lastUpdateTime = 0;

// 处理鼠标按下事件
const handleMouseDown = (event) => {
    isDragging.value = true;
    startX.value = event.clientX;
    
    // 获取当前的左右宽度 - 使用更通用的方法查找容器
    const possibleContainers = [
        '.character-list-page',
        '.image-tool-page', 
        '.text-tool-page'
    ];
    
    let container = null;
    for (const selector of possibleContainers) {
        container = event.target.closest(selector);
        if (container) break;
    }
    
    if (container) {
        let leftElement, rightElement;
        
        if (props.dividerType === 'first') {
            // 第一个分割线：左侧面板和中间面板之间
            const allSidebars = container.querySelectorAll('.character-sidebar, .chat-sidebar');
            leftElement = allSidebars[0]; // 第一个是左侧面板（角色/工具侧边栏）
            rightElement = allSidebars[1]; // 第二个是中间面板（聊天侧边栏）
        } else {
            // 第二个分割线：中间面板和右侧面板之间
            leftElement = container.querySelector('.chat-sidebar');
            // 查找右侧内容区域，支持不同页面的class名称
            rightElement = container.querySelector('.message-area') || 
                container.querySelector('.image-tool-message') ||
                container.querySelector('.chat-main') || 
                container.querySelector('.chat-interface-section');
        }
        
        if (leftElement && rightElement) {
            // 使用 getBoundingClientRect 获得更精确的宽度
            startLeftWidth.value = leftElement.getBoundingClientRect().width;
            startRightWidth.value = rightElement.getBoundingClientRect().width;
        } else {
            console.error('Failed to find elements:', { 
                containerClass: container?.className,
                leftElement: leftElement?.className, 
                rightElement: rightElement?.className, 
                dividerType: props.dividerType 
            });
        }
    } else {
        console.error('Failed to find container with any of:', possibleContainers);
    }

    // 添加全局事件监听
    document.addEventListener('mousemove', handleMouseMove);
    document.addEventListener('mouseup', handleMouseUp);
    
    // 防止文本选择
    event.preventDefault();
};

// 处理鼠标移动事件
const handleMouseMove = (event) => {
    if (!isDragging.value) return;

    // 节流处理：限制更新频率到每10ms一次
    const now = Date.now();
    if (now - lastUpdateTime < 10) return;
    lastUpdateTime = now;

    const deltaX = event.clientX - startX.value;
    const newLeftWidth = Math.max(0, startLeftWidth.value + deltaX);
    const newRightWidth = Math.max(0, startRightWidth.value - deltaX);

    // 直接发出调整事件，让父组件处理限制逻辑
    emit('resize', {
        leftWidth: newLeftWidth,
        rightWidth: newRightWidth,
        deltaX: deltaX
    });
};

// 处理鼠标释放事件
const handleMouseUp = () => {
    isDragging.value = false;
    
    // 移除全局事件监听
    document.removeEventListener('mousemove', handleMouseMove);
    document.removeEventListener('mouseup', handleMouseUp);
};

// 组件卸载时清理事件监听
onUnmounted(() => {
    document.removeEventListener('mousemove', handleMouseMove);
    document.removeEventListener('mouseup', handleMouseUp);
});
</script>

<style scoped lang="scss">
.resizable-divider {
    width: 1px;
    background-color: transparent;
    cursor: col-resize;
    position: relative;
    display: flex;
    align-items: center;
    justify-content: center;
    transition: background-color 0.2s ease;
    flex-shrink: 0;
}

.divider-line {
    width: 1px;
    height: 100%;
    background-color: var(--border-color);
    transition: background-color 0.2s ease;
}


/* 全局样式：防止拖拽时选中文本 */
.resizable-divider.dragging {
    user-select: none;
}

/* 拖拽时为整个页面添加col-resize光标 */
:global(body.resizing) {
    cursor: col-resize !important;
    user-select: none !important;
}
</style> 