<script setup>
import { ref, computed, watch } from "vue";
import { useI18n } from "vue-i18n";
import { ElMessage } from "element-plus";
import LImg from "@/components/l-img.vue";
import { usePromptStore } from "@/store/modules/prompt";
import { ApiCharacter } from "@/api/api-character";
import { calculateAge , copy } from "@/utils/util.js";

const props = defineProps({
    visible: {
        type: Boolean,
        default: false,
    },
    prompt: {
        type: Object,
        default: () => ({
            id: null,
            title: "",
            content: "",
            category: "",
            description: "",
            characterDetails: null,
            creator: "User",
            createdAt: new Date(),
            chats: 0,
        }),
    },
    // 新增：详细数据prop，由父组件传入
    detailData: {
        type: Object,
        default: null,
    },
    // 新增：加载状态prop，由父组件控制
    loading: {
        type: Boolean,
        default: false,
    },
});

const emit = defineEmits([
    "update:visible",
    "delete",
    // 新增：数据加载事件，父组件监听此事件进行数据加载
    "load-detail",
    "edit",
]);

const { t } = useI18n();

// 对话框显示控制
const dialogVisible = ref(false);
// 删除确认对话框控制
const deleteConfirmVisible = ref(false);

// 是否有基本数据
const hasBasicData = computed(() => {
    return (
        props.prompt &&
        (props.prompt.id || props.prompt.category || props.prompt.name)
    );
});

// 显示数据 - 优先使用详细数据，否则使用传入的基本数据
const displayData = computed(() => {
    return props.detailData || props.prompt;
});

// 是否有角色详情数据
const hasCharacterDetails = computed(() => {
    const data = displayData.value;
    return data.characterDetails || data.gender || data.age;
});

const ageStr = computed(() => {
    const data = displayData.value;
    const age = data.characterDetails?.age || data.age || "-";
    return calculateAge(age) ?? "-";
});

// 监听props.visible变化
watch(
    () => props.visible,
    (newVal) => {
        dialogVisible.value = newVal;
        if (newVal) {
            // 弹窗打开时，通知父组件加载详细数据
            const itemId = props.prompt?.id;
            if (itemId) {
                emit("load-detail", itemId);
            }
        }
    }
);

// 监听dialogVisible变化
watch(
    () => dialogVisible.value,
    (newVal) => {
        emit("update:visible", newVal);
    }
);

// 格式化日期
const formatDate = (date) => {
    if (!date) return "";
    const d = new Date(date);
    const month = String(d.getMonth() + 1).padStart(2, "0");
    const day = String(d.getDate()).padStart(2, "0");
    const year = d.getFullYear();
    const hours = String(d.getHours()).padStart(2, "0");
    const minutes = String(d.getMinutes()).padStart(2, "0");

    return `${month}/${day}, ${year} ${hours}:${minutes}`;
};

// 关闭弹窗
const handleClose = () => {
    dialogVisible.value = false;
};

// 复制提示词
const clickCopyPrompt = () => {
    const promptContent = displayData.value.prompt || displayData.value.content;

    try {
        copy(promptContent);
        ElMessage.success(t("copySuccess"));
    } catch (error) {
        ElMessage.error(t("copyFailed"));
    }
};

// 处理删除按钮点击
const handleDelete = () => {
    deleteConfirmVisible.value = true;
};

// 取消删除
const cancelDelete = () => {
    deleteConfirmVisible.value = false;
};

// 确认删除
const confirmDelete = () => {
    // 关闭确认弹窗
    deleteConfirmVisible.value = false;
    // 关闭主弹窗
    dialogVisible.value = false;
    // 发送删除事件给父组件，传递原始数据或详细数据
    emit("delete", displayData.value);
};

const handleEdit = () => {
    emit("edit", displayData.value);
};
</script>

