import { defineStore } from 'pinia';

export const usePromptStore = defineStore('prompt', {
    state: () => ({
        // 提示词弹窗相关状态
        promptDialogVisible: false,  // 控制弹窗显示/隐藏
        currentPrompt: {             // 当前显示的提示词内容
            title: '',               // 提示词标题
            content: '',             // 提示词内容
            category: ''             // 提示词分类
        }
    }),
    
    getters: {
        /**
         * 获取提示词弹窗状态
         * @param state - Pinia state
         * @returns {boolean} - 提示词弹窗是否可见
         */
        isPromptDialogVisible(state) {
            return state.promptDialogVisible;
        },
        
        /**
         * 获取当前提示词信息
         * @param state - Pinia state
         * @returns {object} - 当前提示词信息对象
         */
        getCurrentPrompt(state) {
            return state.currentPrompt;
        }
    },
    
    actions: {
        /**
         * 设置提示词弹窗可见状态
         * @param {boolean} visible - 弹窗是否可见
         */
        setPromptDialogVisible(visible) {
            this.promptDialogVisible = visible;
        },
        
        /**
         * 设置当前提示词信息
         * @param {object} prompt - 提示词信息对象
         */
        setCurrentPrompt(prompt) {
            this.currentPrompt = prompt;
        },
        
        /**
         * 打开提示词弹窗并设置提示词信息
         * @param {object} prompt - 提示词信息对象
         */
        openPromptDialog(prompt) {
            if (prompt) {
                this.setCurrentPrompt(prompt);
            }
            this.setPromptDialogVisible(true);
        },
        
        /**
         * 关闭提示词弹窗
         */
        closePromptDialog() {
            this.setPromptDialogVisible(false);
        }
    },
    
    // persist: {
    //     key: 'prompt-store',
    //     storage: sessionStorage, 
    // },
}); 