<template>
    <el-dialog v-model="dialogVisible" width="25%" :show-close="false" class="def-delete-dialog">
        <template #header>
            <div class="def-title-text">{{ t('confirmDeletion') }}</div>
        </template>
        <div class="def-delete-content">
            <div class="def-line def-line-spacer"></div>
            <div class="content-padding">{{ t('deleteChatMessage') }}</div>
        </div>
        <template #footer>
            <div class="dialog-footer">
                <el-button @click="handleCancel"
                    class="dialog-button">{{ t('cancel') }}</el-button>
                <el-button color="#DF2D29" @click="handleConfirm"
                    class="dialog-button">{{ t('confirm') }}</el-button>
            </div>
        </template>
    </el-dialog>
</template>

<script setup>
import { computed } from 'vue';
import { useI18n } from 'vue-i18n';
import { ElDialog, ElButton } from 'element-plus';

const { t } = useI18n();

// Props
const props = defineProps({
    visible: {
        type: Boolean,
        default: false
    },
    loading: {
        type: Boolean,
        default: false
    }
});

// Emits
const emit = defineEmits(['update:visible', 'confirm', 'cancel']);

// 计算属性
const dialogVisible = computed({
    get: () => props.visible,
    set: (value) => emit('update:visible', value)
});

// 处理取消
const handleCancel = () => {
    emit('cancel');
    emit('update:visible', false);
};

// 处理确认
const handleConfirm = () => {
    emit('confirm');
};
</script>


