<template>
    <div
    ref="containerRef"
    class="infinite-scroll-container"
    :class="[containerClass, { 'empty-content': isEmptyContent && loading }]"
    v-infinite-scroll="onLoadListener"
    :infinite-scroll-disabled="scrollDisabled"
    :infinite-scroll-distance="distance"
    :infinite-scroll-delay="delay"
    :infinite-scroll-immediate="immediate"
  >
    <!-- 主要内容插槽 -->
    <div ref="slotRef" class="slot-content">
      <slot></slot>
    </div>

    <!-- 加载状态指示器 -->
    <div
      v-if="shouldShowIndicator"
      class="scroll-indicator"
      :class="{ 'centered-indicator': (isEmptyContent && loading) || (isEmptyContent && !isFetchSuccess) }"
    >
      <!-- 状态显示优先级：loading > retry > finished -->
      
      <!-- 加载中状态 - 最高优先级 -->
      <div v-if="loading" class="loading-wrapper">
        <el-icon class="is-loading loading-icon">
          <Loading />
        </el-icon>
        <span class="loading-text">{{ loadingText }}</span>
      </div>

      <!-- 重试状态 - 仅在非加载状态下显示 -->
      <div v-if="!isFetchSuccess" class="retry-wrapper">
        <el-icon class="retry-icon">
          <RefreshRight />
        </el-icon>
        <span class="retry-text">{{ t('loadFailed') }}</span>
        <el-button 
          type="primary" 
          size="small" 
          @click="handleRetry"
          class="retry-button"
        >
          {{ retryText }}
        </el-button>
      </div>

      <!-- 没有更多数据状态 - 仅在成功且已完成时显示 -->
      <div v-if="finished" class="finished-wrapper">
        <span class="finished-text">{{ finishedText }}</span>
      </div>
    </div>
    </div>
</template>

<script setup lang="ts">
import { ref, computed, nextTick, onMounted, onUpdated } from "vue";
import { Loading, RefreshRight } from '@element-plus/icons-vue';
import { t } from "../language";

/**
 * 组件事件接口
 */
interface InfiniteScrollEmits {
  /** 触发加载更多 */
  loadMore: [];
  /** 触发重试 */
  retry: [];
}

// Props默认值
const props = defineProps({
  loading: {
    type: Boolean,
    default: false,
  },
  finished: {
    type: Boolean,
    default: false,
  },
  distance: {
    type: Number,
    default: 0,
  },
  delay: {
    type: Number,
    default: 200,
  },
  immediate: {
    type: Boolean,
    default: true,
  },
  disabled: {
    type: Boolean,
    default: false,
  },
  containerClass: {
    type: String,
    required: true,
    default: "",
  },
  loadingText: {
    type: String,
    default: t("loading"),
  },
  finishedText: {
    type: String,
    default: t("noMoreData"),
  },
  retryText: {
    type: String,
    default: t("retry"),
  }
});

// 事件定义
const emit = defineEmits<InfiniteScrollEmits>();

// 模板引用
const containerRef = ref<HTMLDivElement>();
const slotRef = ref<HTMLDivElement>();
const isFetchSuccess = ref(true);

// 检测slot内容是否为空
const isEmptyContent = ref(true);

/**
 * 计算是否禁用滚动加载
 * 当正在加载、已完成、失败或手动禁用时禁用
 */
 const scrollDisabled = computed(
  () => props.loading || props.finished || props.disabled || !isFetchSuccess.value
);

/**
 * 计算是否应该显示状态指示器
 * 当加载中、失败、或已完成时显示
 */
const shouldShowIndicator = computed(() => props.loading || props.finished || !isFetchSuccess.value);

/**
 * 检测slot是否有内容
 */
const checkSlotContent = () => {
  if (slotRef.value) {
    const hasContent =
      slotRef.value.children.length > 0 ||
      slotRef.value.textContent?.trim() !== "";
    isEmptyContent.value = !hasContent;
  }
};

/**
 * 处理无限滚动触发的加载事件
 */
const onLoadListener = () => {
  if (scrollDisabled.value) return;
  emit("loadMore");
};

/**
 * 处理重试事件
 */
const handleRetry = () => {
  isFetchSuccess.value = true;
  emit("loadMore");
};

/**
 * 滚动到容器顶部
 */
const scrollToTop = async (behavior: ScrollBehavior = "smooth") => {
  await nextTick();
  if (containerRef.value) {
    containerRef.value.scrollTo({
      top: 0,
      behavior,
    });
  }
};

/**
 * 滚动到容器底部
 */
const scrollToBottom = async (behavior: ScrollBehavior = "smooth") => {
  await nextTick();
  if (containerRef.value) {
    const container = containerRef.value;
    container.scrollTo({
      top: container.scrollHeight,
      behavior,
    });
  }
};


/**
 * 重置滚动位置到指定位置
 */
const scrollTo = async (top: number, behavior: ScrollBehavior = "smooth") => {
  await nextTick();
  if (containerRef.value) {
    containerRef.value.scrollTo({ top, behavior });
  }
};

const changeIsFetchSuccess = () => {
  isFetchSuccess.value = false;
}

// 生命周期钩子
onMounted(() => {
  checkSlotContent();
});

onUpdated(() => {
  checkSlotContent();
});

// 暴露组件方法
defineExpose({
  scrollToTop,
  scrollToBottom,
  scrollTo,
  containerRef,
  changeIsFetchSuccess,
});
</script>

<style lang="scss" scoped>
