  }
}

.loading-wrapper {
  display: flex;
  align-items: center;
  gap: 8px;
  color: var(--el-text-color-regular);

  .loading-icon {
    font-size: 16px;
    color: var(--el-color-primary);
  }

  .loading-text {
    font-size: 14px;
  }
}

.finished-wrapper {
  width: 100%;
  height: 30px;
  display: flex;
  justify-content: center;
  align-items: center;

  .finished-text {
    font-size: 12px;
    color: var(--el-text-color-placeholder);
  }
}

.retry-wrapper {
  display: flex;
  flex-direction: column;
